-- 176: Original BrillaPrep WASSCE BrillaPrep transitional Metalwork beta content blueprint questions, part 5.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_176_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_176_guard;
INSERT INTO _migration_176_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_021' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_5' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is steel heated to a suitable forging temperature before heavy shaping?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Increase plasticity and reduce the force needed for deformation","B. Make the steel permanently liquid","C. Remove the need for safe tool handling","D. Prevent all scale formation regardless of temperature"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Hot working lowers flow stress so the metal can change shape under blows or pressure without cracking from excessive cold deformation. Therefore the correct answer is A: Increase plasticity and reduce the force needed for deformation.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_5' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_021' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_176_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_022' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_5' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which forging operation reduces cross-section and increases length?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Upsetting","B. Drawing down","C. Punching","D. Fullering only to increase thickness everywhere"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Drawing down redistributes volume into a longer, thinner section through controlled hammering or pressing. Therefore the correct answer is B: Drawing down.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_022' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_176_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_023' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_5' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What happens during upsetting of a heated bar?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Its length increases while section decreases","B. A hole is cut without displacing metal","C. Its cross-section increases as its length decreases locally","D. The surface is coated by solder"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Axial compression gathers material into a thicker region, a common first step for forged heads and shoulders. Therefore the correct answer is C: Its cross-section increases as its length decreases locally.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_023' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_176_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_024' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_5' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why should hot metal be identified and kept in a designated area?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Hot steel always emits visible light until safe","B. Designated areas make tongs unnecessary","C. Cooling metal cannot ignite nearby materials","D. It may look cold while retaining enough heat to cause severe burns"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Metal can fall below visible red heat yet remain dangerously hot, so separation and clear communication prevent accidental contact. Therefore the correct answer is D: It may look cold while retaining enough heat to cause severe burns.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_5' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_024' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_176_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_025' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_5' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the purpose of a fuller in hand forging?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Concentrate blows to spread or reduce metal in a controlled region","B. Measure the final diameter precisely","C. Cut an internal screw thread","D. Join cold sheet edges by soldering"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The rounded working face localises deformation and helps draw down or form shoulders more efficiently than a broad flat blow. Therefore the correct answer is A: Concentrate blows to spread or reduce metal in a controlled region.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_025' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
